            Interop.NativeError.ThrowIfFailed(GeneratedNativeMethods.TopoDSTWireGetReferenceCount(handle, out int value), "generated_shared_get_ref_count");
            return value;
        }
    }

    /// <summary>Gets the registered OCCT runtime type name.</summary>
    public string TypeName
    {
        get
        {
            ObjectDisposedException.ThrowIf(handle.IsClosed, this);
            Interop.NativeError.ThrowIfFailed(GeneratedNativeMethods.TopoDSTWireGetTypeName(handle, out nint value), "generated_shared_get_type_name");
            return Marshal.PtrToStringUTF8(value) ?? string.Empty;
        }
    }

    /// <summary>Checks the OCCT runtime type and base-type relationship.</summary>
    public bool IsKind(string typeName)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(typeName);
        ObjectDisposedException.ThrowIf(handle.IsClosed, this);
        Interop.NativeError.ThrowIfFailed(GeneratedNativeMethods.TopoDSTWireIsKind(handle, typeName, out int value), "generated_shared_is_kind");
        return value != 0;
    }

    /// <summary>Creates another wrapper retaining the same OCCT object.</summary>
    public TopoDSTWire Clone()
    {
        ObjectDisposedException.ThrowIf(handle.IsClosed, this);
        Interop.NativeError.ThrowIfFailed(GeneratedNativeMethods.TopoDSTWireClone(handle, out nint nativeHandle), "generated_shared_clone");
        return new TopoDSTWire(CreateHandle(nativeHandle, "generated_shared_clone"));
    }

    /// <summary>Releases this wrapper's retained OCCT reference.</summary>
    public void Dispose() => handle.Dispose();

    internal TopoDSTWireHandle NativeHandle
    {
        get
        {
            ObjectDisposedException.ThrowIf(handle.IsClosed, this);
            return handle;
        }
    }

    internal static TopoDSTWire? FromNative(nint nativeHandle, string operation) =>
        nativeHandle == 0 ? null : new TopoDSTWire(CreateHandle(nativeHandle, operation));

    private static TopoDSTWireHandle CreateHandle(nint nativeHandle, string operation)
    {
        if (nativeHandle == 0) throw new OcctException("UnknownException", $"Native operation '{operation}' returned a null generated shared handle.");
        return new TopoDSTWireHandle(nativeHandle);
    }
}
